d3.csv("data/stock-descriptions.csv").then(function(data) {
    // Data preparation
    data.forEach(d => {
        d.marketCap = d.marketCap ? +d.marketCap : null;
        d.isETF = d.sector === 'ETF';
    });

    // Filter out rows with empty tickers if any
    data = data.filter(d => d.ticker);

    const width = 800;
    const height = 600;

    const svg = d3.select("#chart-container")
        .append("svg")
        .attr("width", "100%")
        .attr("height", height)
        .attr("viewBox", `0 0 ${width} ${height}`);

    const tooltip = d3.select("#chart-container")
        .append("div")
        .attr("class", "tooltip");

    // Scales
    const sectors = Array.from(new Set(data.map(d => d.sector)));
    const colorScale = d3.scaleOrdinal(d3.schemeCategory10).domain(sectors);

    const marketCaps = data.map(d => d.marketCap).filter(v => v !== null);
    const minCap = d3.min(marketCaps);
    const maxCap = d3.max(marketCaps);

    const radiusScale = d3.scaleSqrt()
        .domain([minCap, maxCap])
        .range([10, 50]);

    const getRadius = d => d.isETF ? 15 : radiusScale(d.marketCap);

    // Cluster centers
    const clusterCenters = {};
    sectors.forEach((sector, i) => {
        const angle = (i / sectors.length) * 2 * Math.PI;
        clusterCenters[sector] = {
            x: width / 2 + Math.cos(angle) * 200,
            y: height / 2 + Math.sin(angle) * 200
        };
    });

    // Simulation
    const simulation = d3.forceSimulation(data)
        .force("x", d3.forceX(d => clusterCenters[d.sector].x).strength(0.15))
        .force("y", d3.forceY(d => clusterCenters[d.sector].y).strength(0.15))
        .force("collide", d3.forceCollide(d => getRadius(d) + 2))
        .force("center", d3.forceCenter(width / 2, height / 2))
        .on("tick", ticked);

    const bubbles = svg.selectAll(".bubble-group")
        .data(data)
        .enter()
        .append("g")
        .attr("class", "bubble-group")
        .on("mouseover", function(event, d) {
            if (!d.isETF) {
                tooltip.style("display", "block")
                    .html(`<strong>Ticker:</strong> ${d.ticker}<br/>
                          <strong>Name:</strong> ${d['full name']}<br/>
                          <strong>Sector:</strong> ${d.sector}`);
            }
        })
        .on("mousemove", function(event) {
            tooltip.style("left", (event.pageX - d3.select("#chart-container").node().getBoundingClientRect().left + 10) + "px")
                   .style("top", (event.pageY - d3.select("#chart-container").node().getBoundingClientRect().top + 10) + "px");
        })
        .on("mouseout", function() {
            tooltip.style("display", "none");
        })
        .on("click", function(event, d) {
            highlightItem(d.ticker);
        });

    bubbles.append("circle")
        .attr("class", "bubble")
        .attr("r", d => getRadius(d))
        .attr("fill", d => colorScale(d.sector));

    bubbles.append("text")
        .attr("class", "bubble-label")
        .text(d => d.ticker)
        .attr("dy", ".3em");

    function ticked() {
        bubbles.attr("transform", d => `translate(${d.x},${d.y})`);
    }

    // Table
    const tableBody = d3.select("#stock-table tbody");
    const rows = tableBody.selectAll("tr")
        .data(data)
        .enter()
        .append("tr")
        .attr("id", d => "row-" + d.ticker)
        .on("click", function(event, d) {
            highlightItem(d.ticker);
        });

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d['full name']);
    rows.append("td").text(d => d.sector);
    rows.append("td").text(d => d.marketCap ? formatMarketCap(d.marketCap) : "N/A");

    function formatMarketCap(val) {
        if (val >= 1e12) return (val / 1e12).toFixed(2) + "T";
        if (val >= 1e9) return (val / 1e9).toFixed(2) + "B";
        if (val >= 1e6) return (val / 1e6).toFixed(2) + "M";
        return val.toLocaleString();
    }

    function highlightItem(ticker) {
        // Reset previous highlights
        d3.selectAll("tr").classed("highlight", false);
        d3.selectAll("circle").style("stroke", "#fff").style("stroke-width", "1.5px");

        // Highlight table row
        const row = d3.select("#row-" + ticker);
        row.classed("highlight", true);
        row.node().scrollIntoView({ behavior: "smooth", block: "nearest" });

        // Highlight bubble
        const bubbleGroup = bubbles.filter(d => d.ticker === ticker);
        bubbleGroup.select("circle")
            .style("stroke", "#333")
            .style("stroke-width", "3px");
    }

    // Legend
    const legendContainer = d3.select("#legend");
    sectors.forEach(sector => {
        const item = legendContainer.append("div").attr("class", "legend-item");
        item.append("div")
            .attr("class", "legend-color")
            .style("background-color", colorScale(sector));
        item.append("span").text(sector);
    });
});
